import pandas as pd
import os
import numpy as np
from surfice_script_generator import write_nodecreate_txt


#df_elec = pd.read_csv("YFU-electrodes_v2025+.csv")
#df_elec["Subject"] = "YFU"
#df_elec = pd.read_csv("CSVs/combined_electrodes.csv")
df_elec = pd.read_csv("CSVs/combined_electrodes_MNI152.csv")

df_circ_power = pd.read_csv("circ_power/circadian_power_24hr_summary.csv")

df_plt = df_circ_power.query("shuffled == False and band == 'delta'")
patients_ = df_plt["patient"].unique()
l_ = []
for p in patients_:
    df_p = df_plt.query("patient == @p")
    chs = df_p["channel"].values
    for ch in chs:
        df_ch = df_p.query("channel == @ch")
        power_val = df_ch["power_24hr"].values[0]
        p_ = p[:3]
        ch_ = ch[:-4]
        df_elec_p = df_elec.query("Subject == @p_ and Label == @ch_")
        if df_elec_p.shape[0] == 0:
            continue
        x = df_elec_p["MNI152_x"].values[0]
        y = df_elec_p["MNI152_y"].values[0]
        z = df_elec_p["MNI152_z"].values[0]
        l_.append({
            "x": x,
            "y": y,
            "z": z,
            "patient": p,
            "power": power_val,
            "channel": ch
        })
df_plot = pd.DataFrame(l_)
df_plot = df_plot.dropna()

write_nodecreate_txt(
    df_plot["x"].values,
    df_plot["y"].values,
    df_plot["z"].values,
    df_plot["power"].values,
    radius=[0.5]*len(df_plot),
    out_file="nodecreate.txt",
    precision=2,
)

